package com.nigson.experience.content;

import java.time.Instant;
import java.util.*;
import java.util.regex.Pattern;
import com.nigson.shared.problem.ApiValues;
import tools.jackson.databind.JsonNode;

public final class CmsValues {
 private CmsValues(){}
 public static final Set<String> TYPES=Set.of("HOME","ABOUT","LEADERSHIP","DIVISION","BLOG","VIDEO","FAQ","CAREERS","CONTACT");
 public static final Set<String> STATES=Set.of("DRAFT","REVIEW","APPROVED","PUBLISHED","WITHDRAWN","ARCHIVED");
 public record Content(UUID id,String type,String slug,String locale,UUID currentRevision,String status,long version){}
 public record Revision(UUID id,UUID contentItemId,int revision,String state,String type,String slug,String locale,String title,JsonNode body,JsonNode metadata,long version,Instant scheduledAt,Instant publishedAt,UUID createdBy,UUID approvedBy,String checksum){}
 public record RevisionDTO(UUID id,UUID contentItemId,int revision,String state,String type,String slug,String locale,String title,JsonNode body,JsonNode metadata,long version,Instant scheduledAt,Instant publishedAt){}
 public record ContentDTO(UUID id,String type,String slug,String locale,int revision,String title,JsonNode body,JsonNode metadata,Instant publishedAt){}
 public record ChannelDTO(UUID id,String kind,String key,JsonNode publicValue,boolean active,long version){}
 public static JsonNode object(JsonNode n,Set<String> allowed,Set<String> required){if(n==null||!n.isObject()||!n.propertyNames().containsAll(required)||!allowed.containsAll(n.propertyNames())||n.propertyNames().size()!=n.size())throw ApiValues.invalid();return n;}
 public static String text(JsonNode n,String key,int max,boolean optional){JsonNode v=n.get(key);if(v==null&&optional)return null;if(v==null||!v.isString())throw ApiValues.invalid();String s=v.asString();if(s.isBlank()||s.length()>max||!s.equals(s.strip())||s.chars().anyMatch(c->c==0||c==127)||(key.equals("text")||key.equals("bio")||key.equals("answer"))&&Pattern.compile("(?i)<\\s*(script|iframe|object|embed)|on[a-z]+\\s*=|javascript:").matcher(s).find())throw ApiValues.invalid();return s;}
 public static String slug(String s){if(s==null||s.length()>220||!s.matches("[a-z0-9]+(?:-[a-z0-9]+)*"))throw ApiValues.invalid();return s;}
 public static String locale(String s){if(s==null||s.length()>16||!s.matches("[A-Za-z]{2,8}(?:-[A-Za-z0-9]{1,8})*"))throw ApiValues.invalid();return s;}
 public static String type(String s){if(!TYPES.contains(s))throw ApiValues.invalid();return s;}
 public static JsonNode seo(JsonNode n){object(n,Set.of("title","description","canonicalUrl","robots","alternates","structuredData"),Set.of("title","description","robots","alternates","structuredData"));text(n,"title",70,false);text(n,"description",180,false);if(!Set.of("INDEX","NOINDEX").contains(text(n,"robots",8,false)))throw ApiValues.invalid();if(n.has("canonicalUrl")&&!n.get("canonicalUrl").isNull())https(n.get("canonicalUrl").asString());JsonNode alts=n.get("alternates");if(!alts.isArray()||alts.size()>30)throw ApiValues.invalid();for(JsonNode a:alts){object(a,Set.of("locale","url"),Set.of("locale","url"));locale(text(a,"locale",16,false));https(text(a,"url",2048,false));}JsonNode structured=n.get("structuredData");if(!structured.isObject()||structured.size()>50||structured.toString().length()>10000)throw ApiValues.invalid();return n;}
 public static JsonNode body(JsonNode n,String type){object(n,Set.of("schemaVersion","blocks"),Set.of("schemaVersion","blocks"));if(!n.get("schemaVersion").isIntegralNumber()||n.get("schemaVersion").intValue()!=1||!n.get("blocks").isArray()||n.get("blocks").size()>200)throw ApiValues.invalid();for(JsonNode b:n.get("blocks"))block(b);if((type.equals("FAQ")||type.equals("BLOG")||type.equals("ABOUT"))&&n.get("blocks").isEmpty())throw ApiValues.invalid();if(n.toString().length()>1_000_000)throw ApiValues.invalid();return n;}
 private static void block(JsonNode b){if(b==null||!b.isObject()||!b.has("type")||!b.get("type").isString())throw ApiValues.invalid();String type=b.get("type").asString();Set<String> keys=switch(type){case "TEXT"->Set.of("type","text");case "IMAGE"->Set.of("type","assetId","alt");case "VIDEO"->Set.of("type","provider","videoId","caption");case "PERSON"->Set.of("type","name","title","bio","assetId");case "LINK"->Set.of("type","label","url");case "MAP"->Set.of("type","channelKey");case "PRODUCT_LIST"->Set.of("type","productIds");case "FAQ"->Set.of("type","question","answer");default->throw ApiValues.invalid();};object(b,keys,keys);switch(type){case "TEXT"->text(b,"text",20000,false);case "IMAGE"->{uuid(b.get("assetId"));text(b,"alt",300,false);}case "VIDEO"->{if(!Set.of("YOUTUBE","VIMEO").contains(text(b,"provider",10,false)))throw ApiValues.invalid();if(!text(b,"videoId",100,false).matches("[A-Za-z0-9_-]{1,100}"))throw ApiValues.invalid();text(b,"caption",500,false);}case "PERSON"->{text(b,"name",160,false);text(b,"title",160,false);text(b,"bio",10000,false);if(!b.get("assetId").isNull())uuid(b.get("assetId"));}case "LINK"->{text(b,"label",160,false);https(text(b,"url",2048,false));}case "MAP"->text(b,"channelKey",80,false);case "PRODUCT_LIST"->{if(!b.get("productIds").isArray()||b.get("productIds").size()>30)throw ApiValues.invalid();for(JsonNode id:b.get("productIds"))uuid(id);}case "FAQ"->{text(b,"question",500,false);text(b,"answer",5000,false);}}}
 public static UUID uuid(JsonNode n){try{if(n==null||!n.isString())throw new IllegalArgumentException();UUID id=UUID.fromString(n.asString());if(id.equals(new UUID(0,0)))throw new IllegalArgumentException();return id;}catch(Exception e){throw ApiValues.invalid();}}
 public static void https(String raw){try{var u=java.net.URI.create(raw);if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getFragment()!=null||u.getHost().endsWith(".invalid"))throw new IllegalArgumentException();}catch(Exception e){throw ApiValues.invalid();}}
 public static RevisionDTO dto(Revision r){return new RevisionDTO(r.id(),r.contentItemId(),r.revision(),r.state(),r.type(),r.slug(),r.locale(),r.title(),r.body(),r.metadata(),r.version(),r.scheduledAt(),r.publishedAt());}
}
